import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift


def shift(worker, day, text):
    return Shift(worker, day, parse_span(text))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        shifts = [
            shift("Ana", "mon", "09:00-10:30"),
            shift("Brisa", "mon", "09:00-13:00"),
            shift("Brisa", "tue", "09:00-12:30"),
            shift("Ana", "tue", "09:00-09:20")
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Brisa: 2 shifts, 7.5 hours", "Ana: 2 shifts, 1.8 hours"]
        )

    def test_ties_break_on_shift_count_then_name(self):
        shifts = [
            shift("Zed", "mon", "09:00-11:00"),
            shift("Amy", "mon", "09:00-10:00"),
            shift("Amy", "tue", "09:00-10:00"),
            shift("Bob", "mon", "09:00-11:00")
        ]
        names = [line.split(":")[0] for line in timesheet_lines(shifts)]
        self.assertEqual(names, ["Amy", "Bob", "Zed"])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([shift("  ", "mon", "09:00-10:00")])
